files.content:
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #eaeaea;
  --muted: #8a8fa3;
  --pixel: 4px;
  font-size: 16px;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  background-image: linear-gradient(45deg, #1a1a2e 25%, transparent 25%),
    linear-gradient(-45deg, #1a1a2e 25%, transparent 25%),
    linear-gradient(45deg, transparent 75%, #1a1a2e 75%),
    linear-gradient(-45deg, transparent 75%, #1a1a2e 75%);
  background-size: 8px 8px;
  background-position: 0 0, 0 4px, 4px -4px, -4px 0;
  background-color: #12121f;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  color: var(--text);
  padding: 16px;
}

.app {
  width: 100%;
  max-width: 420px;
}

.card {
  background: var(--card);
  border: var(--pixel) solid #0f0f1a;
  box-shadow: 8px 8px 0 #0f0f1a;
  padding: 32px 24px;
  text-align: center;
  image-rendering: pixelated;
}

.title {
  font-size: 1.25rem;
  letter-spacing: 2px;
  margin-bottom: 24px;
  color: var(--accent);
  text-shadow: 2px 2px 0 #0f0f1a;
}

.mode-switch {
  display: flex;
  gap: 8px;
  justify-content: center;
  margin-bottom: 24px;
}

.mode-btn {
  font: inherit;
  font-size: 0.875rem;
  font-weight: 700;
  letter-spacing: 1px;
  padding: 8px 16px;
  background: #0f0f1a;
  color: var(--muted);
  border: 2px solid #0f0f1a;
  cursor: pointer;
  transition: background 0.1s, color 0.1s, transform 0.05s;
}

.mode-btn.active {
  background: var(--accent);
  color: #fff;
  border-color: var(--accent);
}

.mode-btn:hover {
  color: var(--text);
  border-color: var(--muted);
}

.mode-btn:active {
  transform: translateY(2px);
}

.mode-btn:focus-visible {
  outline: 3px solid #fff;
  outline-offset: 2px;
}

.timer {
  font-size: clamp(3.5rem, 18vw, 5.5rem);
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  letter-spacing: 4px;
  color: var(--text);
  text-shadow: 4px 4px 0 #0f0f1a;
  margin-bottom: 32px;
  line-height: 1;
}

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  margin-bottom: 20px;
}

.btn {
  font: inherit;
  font-size: 1rem;
  font-weight: 700;
  letter-spacing: 1px;
  padding: 12px 24px;
  background: var(--accent);
  color: #fff;
  border: 3px solid #0f0f1a;
  box-shadow: 4px 4px 0 #0f0f1a;
  cursor: pointer;
  transition: transform 0.05s, box-shadow 0.05s, background 0.1s;
}

.btn:hover {
  background: #ff5c77;
}

.btn:active {
  transform: translate(4px, 4px);
  box-shadow: 0 0 0 #0f0f1a;
}

.btn:focus-visible {
  outline: 3px solid #fff;
  outline-offset: 2px;
}

.btn.reset {
  background: #2a2a4a;
}

.btn.reset:hover {
  background: #3a3a5a;
}

.hint {
  font-size: 0.875rem;
  color: var(--muted);
}

@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
  }
  .btn {
    padding: 12px 16px;
    font-size: 0.875rem;
  }
  .mode-btn {
    padding: 8px 12px;
    font-size: 0.75rem;
  }
}

(function () {
  'use strict';

  const WORK_SECONDS = 25 * 60;
  const BREAK_SECONDS = 5 * 60;

  const display = document.getElementById('timerDisplay');
  const startPauseBtn = document.getElementById('startPauseBtn');
  const resetBtn = document.getElementById('resetBtn');
  const modeWork = document.getElementById('modeWork');
  const modeBreak = document.getElementById('modeBreak');

  let mode = 'work';
  let remaining = WORK_SECONDS;
  let running = false;
  let intervalId = null;
  let endTime = 0;

  function format(seconds) {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return String(m).padStart(2, '0') + ':' + String(s).padStart(2, '0');
  }

  function updateDisplay() {
    display.textContent = format(remaining);
  }

  function setMode(newMode) {
    mode = newMode;
    stopTimer();
    remaining = mode === 'work' ? WORK_SECONDS : BREAK_SECONDS;
    updateDisplay();
    modeWork.classList.toggle('active', mode === 'work');
    modeBreak.classList.toggle('active', mode === 'break');
    modeWork.setAttribute('aria-pressed', String(mode === 'work'));
    modeBreak.setAttribute('aria-pressed', String(mode === 'break'));
    startPauseBtn.textContent = 'START';
    startPauseBtn.setAttribute('aria-label', 'Start timer');
  }

  function tick() {
    const now = Date.now();
    const diff = Math.max(0, Math.round((endTime - now) / 1000));
    if (diff !== remaining) {
      remaining = diff;
      updateDisplay();
    }
    if (remaining <= 0) {
      stopTimer();
      startPauseBtn.textContent = 'START';
      startPauseBtn.setAttribute('aria-label', 'Start timer');
    }
  }

  function startTimer() {
    if (running || remaining <= 0) return;
    running = true;
    endTime = Date.now() + remaining * 1000;
    intervalId = setInterval(tick, 250);
    startPauseBtn.textContent = 'PAUSE';
    startPauseBtn.setAttribute('aria-label', 'Pause timer');
  }

  function stopTimer() {
    running = false;
    if (intervalId !== null) {
      clearInterval(intervalId);
      intervalId = null;
    }
  }

  function toggleTimer() {
    if (running) {
      stopTimer();
      startPauseBtn.textContent = 'START';
      startPauseBtn.setAttribute('aria-label', 'Start timer');
    } else {
      startTimer();
    }
  }

  function resetTimer() {
    stopTimer();
    remaining = mode === 'work' ? WORK_SECONDS : BREAK_SECONDS;
    updateDisplay();
    startPauseBtn.textContent = 'START';
    startPauseBtn.setAttribute('aria-label', 'Start timer');
  }

  startPauseBtn.addEventListener('click', toggleTimer);
  resetBtn.addEventListener('click', resetTimer);
  modeWork.addEventListener('click', function () { setMode('work'); });
  modeBreak.addEventListener('click', function () { setMode('break'); });

  updateDisplay();
})();
